import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火天大有","description":"周易折中 - 火天大有","frontmatter":{"title":"火天大有","description":"周易折中 - 火天大有"},"headers":[],"relativePath":"zh/classics/zhezhong/020.md","filePath":"zh/classics/zhezhong/020.md"}'),h={name:"zh/classics/zhezhong/020.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="火天大有" tabindex="-1">火天大有 <a class="header-anchor" href="#火天大有" aria-label="Permalink to “火天大有”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>《大有》有序卦与人同者，物必归焉，故受之以《大有》。夫与人同者，物之所归也。《大有》所以次《同人》也。为卦火在天上，火之处高，其明及远，万物之众无不照见，为《大有》之象。又一柔居尊，众阳并应，居尊执柔，物之所归也。上下应之，为《大有》之义。《大有》，盛大、丰有也。</p><p>大有：元亨</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>“大有”所有之大也。离居乾土，火在天上，无所不照。又六五一阴居尊得中，而五阳应之，故为“大有”。乾健离明，居尊应天，有亨之道。占者有其德，则大善而亨也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>卦之才可以元亨也。凡卦德、卦名自有其义者，如“比吉”、“谦亨”是也。有因其卦义便为训戒者，如“师贞丈人吉”、“同人于野亨”是也。有以其卦才而言者，“大有元亨”是也。由刚健文明，应天时行，故能元亨也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>郑氏汝谐曰 ：阳为大，阴为小。一阴居尊，而为五阳所归，所有者大也。大非阴柔所能有，必冲虚不自满者能有之。六五明体而虚中，所以为“大有”，所以为“元亨”。若直以“大有”为富有盛大，则失其义矣。</li></ul><p>郑氏汝谐曰 ：阳为大，阴为小。一阴居尊，而为五阳所归，所有者大也。大非阴柔所能有，必冲虚不自满者能有之。六五明体而虚中，所以为“大有”，所以为“元亨”。若直以“大有”为富有盛大，则失其义矣。</p><ul><li>邱氏富国曰 ：一阴在上卦之中，而五阳宗之，诸爻之有皆六五之有也，岂不大哉？惟其所有者大，故其亨亦大也。</li></ul><p>邱氏富国曰 ：一阴在上卦之中，而五阳宗之，诸爻之有皆六五之有也，岂不大哉？惟其所有者大，故其亨亦大也。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>比以九居五，视大有之六五为优矣。然比之应之者五阴也，则民庶之象也；大有之应之者五阳也，则贤人之象也。贤人应之，所有孰大于是哉？故大有之柔中虽不如比之刚中，而比之吉无咎，则不如大有之直言元亨也。彖辞直言元亨，更无他辞者，惟此与鼎卦而已，皆以尚贤养贤之故也。</p><p>象曰：火在天上，大有；君子以遏恶扬善，顺天休命</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>火在天上，所照者广，为大有之象。所有既大，无以治之，则衅蘖萌于其间矣。天命有善而无恶，故遏恶扬善，所以顺天。反之于身，亦若是而已矣。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>火高在天上，照见万物之众多，故为大有。大有繁庶之义。君子观大有之象，以遏绝众恶，扬明善类，以奉顺天休美之命。万物众多，则有善恶之殊。君子享大有之盛，当代天工治养庶类。治众之道在遏恶扬善而已。恶惩善劝，所以顺天命而安群生也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：大有包容之象也，故遏恶扬善，成物之美，顺夫天德，休物之命。</p></li><li><p>司马氏光曰 ：火在天上，明之至也。至明则善恶无所逃，善则举之，恶则抑之。庆赏刑威得其当，然后能保有四方，所以顺天休命也。</p></li><li><p>杨氏万里曰 ：天讨有罪，吾遏之以天；天命有德，吾扬之以天。吾何与焉？此舜禹有天下而不与也，故曰顺天休命。同人离在下而权不敢专，故止于类而辨；大有离在上而权由己出，故极于遏而扬。</p></li></ul><p>彖曰：大有柔得尊位大中，而上下应之，曰大有</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名义，柔谓六五，上下谓五阳。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>言卦之所以为大有也。五以阴居君位，柔得尊位也。处中得大中之道也，为诸阳所宗，上下应之也。夫居尊执柔，固众之所归也。而又有虚中文明、大中之徳，故上下同志应之，所以为大有也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：谓五也。大者皆见有于五，故曰大有。</p></li><li><p>郭氏忠孝曰：柔得尊位大中，谦以居之，不自满假者也。以一柔而应五刚，所谓所宝惟贤，光天之下，万邦黎献共惟帝臣。不如是，不足以为尚贤也。</p></li><li><p>杨氏万里曰：同人、大有一柔五刚均也。柔在下者，曰得位、曰得中、曰应乎干而为同人，我同乎彼之辞也；柔在上者，曰尊位、曰大中、曰上下应而为大有，我有其大之辞也。</p></li><li><p>项氏安世曰：一阴在下，势不足以有众，能推所有以同乎人者也，故名曰同人；一阴在上，人同乎我，为我所有者也，故名曰大有。《彖》于同人曰“应乎乾”，明我应之也；于大有曰“上下应之”，明人应我也。履卦柔在下，亦曰“应乎干”；小畜柔在上，亦曰“上下应之”。此可以推卦例矣。</p></li><li><p>胡氏炳文曰：或曰，小畜亦五阳一阴之卦，主巽之一阴则曰小，此主离之一阴则曰大，何也？曰，巽之一阴在四，欲畜上下五阳，其势逆而难；离之一阴在五，而有上下五阳，其势顺而易。</p></li></ul><p>其德刚健而文明，应乎天而时行，是以元亨</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦徳、卦体释卦辞，应天指六五也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>卦之徳，内刚健而外文明。六五之君，应于干之九二。五之性柔顺而明，能顺应乎二。二干之主也，是应乎干也。顺应乾行，顺乎天时也，故曰“应乎天而时行”。其徳如此，是以元亨也。王弼云：“不大通何由得大有乎？大有则必元亨矣。”此不识卦义，离干成大有之义，非大有之义。便有元亨，由其才故得元亨。大有而不善者与不能亨者有矣。诸卦具元亨利贞，则彖皆释为大亨，恐疑与乾坤同也。不兼利贞，则释为元亨，尽元义也。元有大善之义。有元亨者四卦：大有、蛊、升、鼎也。惟升之彖误随他卦作大亨。曰：“诸卦之元与干不同，何也？”曰：“元之在干，为元始之义，为首出庶物之义。他卦则不能有此义，为善为大而已。”曰：“元之为大可矣，为善何也？”曰：“元者，物之先也。物之先岂有不善者乎？事成而后有败，败非先成者也；兴而后有衰，衰固后于兴也；得而后有失，非得则何以有失也？至于善恶治乱是非，天下之事莫不皆然，必善为先。故《文言》曰：‘元者，善之长也。’”</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：徳应于天，则行不失时矣。刚健不滞，文明不犯。应天则大，时行无违，是以元亨。</p></li><li><p>项氏安世曰：同人、大有两卦，皆以离之中爻为主，而以干为应者也。同人离在下，以徳为主，故曰“应乎干”，者应其徳也；大有离在上，以位为主，故曰“应乎天而时行”，者应其命也。履兑在下曰“应乎干”，大畜艮在上曰“应乎天”，亦卦例也。案卦辞未有不根卦名而繋者，况柔中居尊，能有众阳，是虚心下贤之君，而众君子皆为之用，其亨孰大于是哉？彖传又推卦徳、卦体以尽其缊，其实皆不出乎卦名之中也。程传谓卦名未足以致元亨，由卦才而得元亨者，恐非易之通例。</p></li></ul><p>初九：无交害，匪咎，艰则无咎</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>虽当大有之时，然以阳居下，上无系应，而在事初，未涉乎害者也。何咎之有？然亦必艰以处之，则无咎。戒占者宜如是也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>九居大有之初，未至于盛处，平无应与，未有骄盈之失，故无交害。未涉于害也。大凡富有鲜不有害，以子贡之贤，未能尽免，况其下者乎？匪咎艰则无咎，言富有本匪有咎也，人因富有自为咎耳。若能享富有而知难处，则自无咎也。处富有而不能思艰兢畏，则骄侈之心生矣，所以有咎也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><p>胡氏炳文曰：当大有之时，反易有害。初阳在下，未与物接，所以未涉于害也。何咎之有？然以为匪咎而以易心处之，反有咎矣。无交害，大有之初如此；艰则无咎，大有自初至终皆当如此。</p><p>象曰：大有初九，无交害也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>在大有之初，克念艰难，则骄溢之心无由生矣，所以不交涉于害也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>陆氏振奇曰 ：保终之道，慎于厥始。必有克艰于初，而后有天祐于终。故初曰“大有初九”，上曰“大有上吉”，独本末见大有焉。</p></li><li><p>黄氏淳耀曰 ：无交害者，以九居初，是初心未变，无交故无害也。若过此而有交，则有害矣，安得不慎终如始而一以艰处之也？</p></li></ul><p>九二：大车以载，有攸往，无咎</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>刚中在下，得应乎上，为大车以载之象。有所往而如是，可无咎矣。占者必具此德，乃应其占也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>九以阳刚居二，为六五之君所倚任。刚健则才胜，居柔则谦顺，得中则无过。其才如此，所以能胜大有之任。如大车之材强壮，能胜载重物也，可以任重行远，故有攸往而无咎也。大有丰盛之时，有而未极，故以二之才可往而无咎。至于盛极，则不可以往矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><p>王氏弼曰：任重而不危。</p><p>象曰：大车以载，积中不败也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>壮大之车，重积载于其中而不损败，犹九二材力之强，能胜大有之任也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：道积于中，无所往而不利，如大车之不可败也。</p></li><li><p>吴氏曰 ：慎曰“积中不败”与《诗》言“不输尔载”相似。</p></li></ul><p>九三：公用亨于天子，小人弗克</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>亨（春秋传作“享”，谓朝献也。古者亨通之“亨”、享献之“享”、烹饪之“烹”皆作“亨”字）。九三居下之上，公侯之象，刚而得正，上有六五之君虚中下贤，故为“享于天子”之象。占者有其德，则其占如是；小人无刚正之德，则虽得此爻不能当也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三居下体之上，在下而居人上，诸侯人君之象也。公侯上承天子，天子居天下之尊，率土之滨莫非王臣。在下者何敢专其有？凡土地之富、人民之众，皆王者之有也。此理之正也。故三当大有之时，居诸侯之位，有其富盛，必用亨通乎天子，谓以其有为天子之有也，乃人臣之常义也。若小人处之，则专其富有以为私，不知公以奉上之道，故曰“小人弗克”也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><p>朱子语类云：古文无“享”字，“亨”、“享”、“烹”并通用。如“公用亨于天子”，解作“亨”字便不是。又曰：“亨”、“享”二字据说文本是一字，故《易》中多互用。如“王用亨于岐山”亦当为“享”，如“王用享于帝”之云也。字画音韵是经中浅事，故先儒得其大者多不留意，然不知此等处不理会，却枉费了无限辞说牵补，而卒不得其大义，亦甚害事也。</p><p>象曰：公用亨于天子，小人害也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>公当用亨于天子，若小人处之，则为害也。自古诸侯能守臣节，忠顺奉上者，则蕃养其众以为王之屏翰，丰殖其财以待上之徴赋。若小人处之，则不知为臣奉上之道，以其为己之私，民众财丰则反擅其富强，益为不顺。是小人大有则为害，又大有为小人之害也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>方氏应祥曰 ：爻言“小人弗克”，传言“小人害”。弗克则必至于害矣。</li></ul><p>九四：匪其彭，无咎</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>彭字音义未详（程传曰：盛貌）。理或当然，六五柔中之君，九四以刚近之，有僭逼之嫌。然以其处柔也，故有不极其盛之象，而得无咎。戒占者宜如是也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>九四居大有之时，已过中矣，是大有之盛者也。过盛则凶咎所由生也。故处之之道，“匪其彭”则得无咎。谓能谦损，不处其太盛，则得无咎也。四近君之高位，苟处太盛，则致凶咎。“彭”，盛多之貌。《诗·载驱》云：“汶水汤汤，行人彭彭。”行人盛多之状。《雅·大明》云：“驷騵彭彭”，言武王戎马之盛也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><p>沈氏该曰：以刚处柔，谦以自居，而惧以戒其盛，得明哲保身之义，故无咎也。</p><p>匪其彭，无咎；眀辨晰也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>晰：明貌。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>能不处其盛而得无咎者，盖有明辨之智也。晰：明智也。贤智之人明辨物理，当其方盛，则知咎之将至，故能损抑，不敢至于满极也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>梁氏寅曰 ：谓之明辨而又谓之晰者，见其明智之极也。</li></ul><p>六五：厥孚交如，威如，吉。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>大有之世，柔顺而中以处尊位，虚己以应九二之贤，而上下归之，是其孚信之交也。然君道贵刚，太柔则废，当以威济之则吉。故其象占如此，亦戒辞也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五当大有之时，居君位，虚中为孚信之象。人君执柔守中，而以孚信接于下，则下亦尽其信诚以事于上，上下孚信相交也。以柔居尊位，当大有之时，人心安易，若专尚柔顺，则陵慢生矣。故必威如则吉。“威如”有威严之谓也。既以柔和孚信接于下，众志说从，又有威严使之有畏，善处有者也，吉可知矣。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰：既有诚信以接下而人信之，又有威严以自重而人畏之，为大有之君而刚柔得宜如此，故吉。</li></ul><p>象曰：厥孚交如，信以发志也，威如之吉，易而无备也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>一人之信，足以发上下之志也。太柔则人将易之而无畏备之心。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>下之志从乎上者也。上以孚信接于下，则下亦以诚信事其上，故厥孚交如。由上有孚信以发其下孚信之志，下之从上犹响之应声也。威如之所以吉者，谓若无威严，则下易慢而无戒备也。谓无恭畏备上之道，备谓备上之求责也。</p><h3 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h3><ul><li>孔氏颖达曰 ：信以发志者，释“厥孚交如”之义，由已诚信发起其志，故上下应之，与之交接也。易而无备者，释“盛如之吉”之义，所以威如者，以已不私于物，惟行简易，无所防备，物自畏之，故云易而无备。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>孔氏之说亦有理，盖言威如则疑于上下相防矣，故申之曰易而无备，明乎遏恶扬善，顺理而行，非有所戒备也。</p><p>上九：自天祐之，吉无不利。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>大有之世，以刚居上而能下从六五，是能履信思顺而尚贤也，满而不溢，故其占如此。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上九在卦之终，居无位之地，是大有之极而不居其有者也。处离之上，明之极也。惟至明所以不居其有，不至于过极也。有极而不处，则无盈满之灾，能顺乎理者也。五之孚信而履其上为蹈履诚信之义，五有文明之德，上能降志以应之，为尚贤崇善之义。其处如此，合道之至也，自当享其福庆。自天祐之，行顺乎天而获天祐，故所往皆吉，无所不利也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：系辞曰，“祐者助也，天之所助者顺也，人之所助者信也”。履信思乎顺，又以尚贤也。六五之君实尽此而言于上九者，盖言大有之吉以此终也。故象曰“大有上吉”，则知此吉大有之吉也，非止上九之吉也。</li></ul><p>郭氏雍曰 ：系辞曰，“祐者助也，天之所助者顺也，人之所助者信也”。履信思乎顺，又以尚贤也。六五之君实尽此而言于上九者，盖言大有之吉以此终也。故象曰“大有上吉”，则知此吉大有之吉也，非止上九之吉也。</p><ul><li>郑氏汝谐曰 ：履信思顺，又以尚贤，盖言五也。五“厥孚交如”履信也，居尊用柔思顺也，上九在上尚贤也。五获天之祐，吉无不利，由其有是也。言五而系之上，何也？五成卦之主，上其终也。五之德宜获是福于终可验也。易之取义若是者众，小畜之上九曰“妇贞厉，月几望”，言六四之畜阳至上而为贞厉之妇、几望之月也。若指上九而言，则上九阳也，不得为妇与月。说易者其失在于泥爻以求义，故以履信思顺尚贤归之于上九也。易之所谓“尚”者上也，五尚上九之贤，故自天之祐于上九见之。</li></ul><p>郑氏汝谐曰 ：履信思顺，又以尚贤，盖言五也。五“厥孚交如”履信也，居尊用柔思顺也，上九在上尚贤也。五获天之祐，吉无不利，由其有是也。言五而系之上，何也？五成卦之主，上其终也。五之德宜获是福于终可验也。易之取义若是者众，小畜之上九曰“妇贞厉，月几望”，言六四之畜阳至上而为贞厉之妇、几望之月也。若指上九而言，则上九阳也，不得为妇与月。说易者其失在于泥爻以求义，故以履信思顺尚贤归之于上九也。易之所谓“尚”者上也，五尚上九之贤，故自天之祐于上九见之。</p><ul><li>王氏宗传曰 ：六五以一柔有五刚，上九独在五上，五能尚之。系辞传所谓“又以尚贤”，则上九是也。祐之自天，吉无不利，谓大有至此愈有隆而无替也。然则当大有之极，莫大于得天，而所以得天又莫大于尚贤也。</li></ul><p>王氏宗传曰 ：六五以一柔有五刚，上九独在五上，五能尚之。系辞传所谓“又以尚贤”，则上九是也。祐之自天，吉无不利，谓大有至此愈有隆而无替也。然则当大有之极，莫大于得天，而所以得天又莫大于尚贤也。</p><ul><li>胡氏炳文曰 ：小畜上九畜之终也，其占曰“厉”曰“凶”，承六四言也。大有上九有之终也，其占“吉无不利”，承六五言也。小畜一阴畜众阳，故其终也如彼；大有一阴有众阳，故其终也如此。君臣大分岂不明哉？盖五之“厥孚履信”也，柔中思顺也，尚上九之一阳尚贤也，所以其终也“自天祐之，吉无不利”也。</li></ul><p>胡氏炳文曰 ：小畜上九畜之终也，其占曰“厉”曰“凶”，承六四言也。大有上九有之终也，其占“吉无不利”，承六五言也。小畜一阴畜众阳，故其终也如彼；大有一阴有众阳，故其终也如此。君臣大分岂不明哉？盖五之“厥孚履信”也，柔中思顺也，尚上九之一阳尚贤也，所以其终也“自天祐之，吉无不利”也。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>传义皆以“履信思顺尚贤”为上九之事，然《易》中以上爻终五爻之义者甚多，如“师”之大君有命，“离”之王用出征，“解”之公用射隼，皆非以上爻为王公也。蒙五爻而终其义尔。郭氏、郑氏、王氏之说皆与卦意爻义合，胡氏最为恪守本义者，于此独从郭氏诸说，则亦未允于心故也。</p><p>象曰：大有上吉，自天祐也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>大有之上有极当变，由其所为顺天合道，故天祐助之，所以吉也。君子满而不溢，乃天祐也。系辞复申之曰：“天之所助者顺也，人之所助者信也。”履信思乎顺，又以尚贤也，是以自天祐之吉，无不利也。履信谓履五五虗中信也，思顺谓谦退不居，尚贤谓志从于五。大有之世，不可以盈丰而复处盈焉，非所宜也。六爻之中，皆乐据权位，惟初上不处其位，故初九无咎，上九无不利。上九往上履信思顺，故在上而得吉，盖自天祐也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：象传曰“大有上吉”，明事闗全卦，非止上爻也。此犹师之上六论师之事至此而终，其言大君，盖指六五，非谓上六为大君也。</p></li><li><p>赵氏彦肃曰 ：五能尊上，此大有所以上吉也。君之大有，极于尊贤。</p></li></ul>',123)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
